INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (121, 352, 'Coated paper', '../upload/image/20181227/20181227121547_13713.jpg', '<p><span style="font-size:18px;color:#009900;">Coated paper </span><br/> <span style="font-size:18px;color:#009900;">LWC paper ( Low-weight coated paper )</span><br/> <span style="font-size:18px;color:#009900;">LWC(low-weight coated/light-weight coated ) paper products with GRM is from 48 GRM to 100GRM with outstanding quality . </span><br/> <span style="font-size:18px;color:#009900;">Featuring:</span><br/> <span style="font-size:18px;color:#009900;">Brightness(ISO) : 84 % ISO. </span><br/> <span style="font-size:18px;color:#009900;">Opacity : 90% </span><br/> <span style="font-size:18px;color:#009900;">GlossTS 43% , </span><br/> <span style="font-size:18px;color:#009900;">Gloss BS 43% </span><br/> <span style="font-size:18px;color:#009900;">Size : In sheet---889*1194,787*1092; </span><br/> <span style="font-size:18px;color:#009900;">In roll --- 760-1050*11000.</span><br/></p><p><span style="font-size:18px;color:#009900;">Our tech data of this goods following</span></p> <p><span style="font-size:18px;color:#009900;"><br/> </span></p> <p><span style="font-size:18px;color:#009900;"><img alt="" src="../upload/image/20211216/20211216140425_69966.jpg"/><img alt="" src="../upload/image/20211216/20211216140426_64063.jpg"/><img alt="" src="../upload/image/20211216/20211216140426_61860.jpg"/><img alt="" src="../upload/image/20211216/20211216140427_46411.jpg"/><br/> </span></p>', '2026-09-06 20:58:45');